cat > /tmp/probe/rows.py <<'EOF'
import sys
from png import decode, pixel
w,h,ch,px = decode(sys.argv[1])
t = tuple(int(sys.argv[2][i:i+2],16) for i in (0,2,4))
tol = int(sys.argv[3]) if len(sys.argv)>3 else 4
rows={}; cols={}
for y in range(h):
    for x in range(w):
        c=pixel(px,w,ch,x,y)
        if all(abs(c[i]-t[i])<=tol for i in range(3)):
            rows.setdefault(y,[x,x]); rows[y][0]=min(rows[y][0],x); rows[y][1]=max(rows[y][1],x)
            cols.setdefault(x,[y,y]); cols[x][0]=min(cols[x][0],y); cols[x][1]=max(cols[x][1],y)
ys=sorted(rows)
# group consecutive rows
groups=[]
for y in ys:
    if groups and y<=groups[-1][1]+1: groups[-1][1]=y; groups[-1][2]=min(groups[-1][2],rows[y][0]); groups[-1][3]=max(groups[-1][3],rows[y][1])
    else: groups.append([y,y,rows[y][0],rows[y][1]])
print('row groups (ymin,ymax,xmin,xmax):',groups)
xs=sorted(cols)
g2=[]
for x in xs:
    if g2 and x<=g2[-1][1]+1: g2[-1][1]=x; g2[-1][2]=min(g2[-1][2],cols[x][0]); g2[-1][3]=max(g2[-1][3],cols[x][1])
    else: g2.append([x,x,cols[x][0],cols[x][1]])
print('col groups (xmin,xmax,ymin,ymax):',g2)
EOF
cat > /tmp/probe/diff.py <<'EOF'
import sys
from png import decode, pixel
w,h,ch,a = decode(sys.argv[1])
w2,h2,ch2,b = decode(sys.argv[2])
minx,maxx,miny,maxy=w,0,h,0; n=0
for y in range(min(h,h2)):
    for x in range(min(w,w2)):
        if pixel(a,w,ch,x,y)!=pixel(b,w2,ch2,x,y):
            n+=1; minx=min(minx,x);maxx=max(maxx,x);miny=min(miny,y);maxy=max(maxy,y)
print('sizes',(w,h),(w2,h2),'diff px:',n,'bbox:',(minx,miny,maxx,maxy) if n else None)
